def _collapse_widths(
    cls,
    widths: List[int],
    wrapable: List[bool],
    max_width: int,
    minimum_widths: Optional[List[int]] = None,
) -> List[int]:
    """Reduce widths so that the total is under max_width.

    Args:
        widths (List[int]): List of widths.
        wrapable (List[bool]): List of booleans that indicate if a column may shrink.
        max_width (int): Maximum width to reduce to.
        minimum_widths (List[int], optional): Smallest width each column may
            shrink to. Defaults to zero for every column.

    Returns:
        List[int]: A new list of widths.
    """
    if minimum_widths is None:
        minimum_widths = [0] * len(widths)
    total_width = sum(widths)
    excess_width = total_width - max_width
    if any(wrapable):
        while total_width and excess_width > 0:
            # Only columns above their minimum width may still shrink
            shrinkable = [
                allow_wrap and width > minimum
                for width, allow_wrap, minimum in zip(
                    widths, wrapable, minimum_widths
                )
            ]
            if not any(shrinkable):
                break
            max_column = max(
                width for width, can_shrink in zip(widths, shrinkable) if can_shrink
            )
            second_max_column = max(
                width if can_shrink and width != max_column else 0
                for width, can_shrink in zip(widths, shrinkable)
            )
            column_difference = max_column - second_max_column
            ratios = [
                (1 if (width == max_column and can_shrink) else 0)
                for width, can_shrink in zip(widths, shrinkable)
            ]
            if not any(ratios) or not column_difference:
                break
            max_reduce = [
                min(excess_width, column_difference, width - minimum)
                for width, minimum in zip(widths, minimum_widths)
            ]
            widths = ratio_reduce(excess_width, ratios, max_reduce, widths)

